"use strict";function renderPage(n,t){pageRendering=!0;pdfDoc.getPage(n).then(function(n){var i=n.getViewport(t),r,u;canvas.height=i.height;canvas.width=i.width;r={canvasContext:ctx,viewport:i};u=n.render(r);u.promise.then(function(){pageRendering=!1;pageNumPending!==null&&(renderPage(pageNumPending),pageNumPending=null)})});$("#page_count").removeClass("hidden");document.getElementById("page_num").value=n}function queueRenderPage(n){pageRendering?pageNumPending=n:renderPage(n,scale)}function onPrevPage(){if(!(pageNum<=1)){pageNum--;var n=pdfDoc.scale;queueRenderPage(pageNum,n)}}function onNextPage(){if(!(pageNum>=pdfDoc.numPages)){pageNum++;var n=pdfDoc.scale;queueRenderPage(pageNum,n)}}var pdfDoc=null,pageNum=1,pageRendering=!1,pageNumPending=null,scale=5,zoomRange=.2,canvas=document.getElementById("the-canvas"),ctx=canvas.getContext("2d");document.getElementById("prev").addEventListener("click",onPrevPage);document.getElementById("next").addEventListener("click",onNextPage);PDFJS.getDocument(url).then(function(n){pdfDoc=n;var t=pdfDoc.numPages;document.getElementById("page_count").textContent="/ "+t;$("#page_num").on("change",function(){var n=Number($(this).val());n>0&&n<=t&&queueRenderPage(n,scale)});renderPage(pageNum,scale)});